INSERT INTO sys_agent_task_event (
    task_id, event_type, step_order, actor_type, actor_id,
    from_status, to_status, detail_json, created_time
) VALUES (
    #{taskId}, #{eventType}, #{stepOrder}, #{actorType}, #{actorId},
    #{fromStatus}, #{toStatus}, #{detailJson}, #{createdTime}
)

mapper.select:
SELECT event.id, event.task_id, event.event_type, event.step_order,
       event.actor_type, event.actor_id, event.from_status, event.to_status,
       event.detail_json, event.created_time
FROM sys_agent_task_event event
INNER JOIN sys_agent_task task ON task.task_id = event.task_id
WHERE event.task_id = #{taskId}
  AND task.operator_id = #{operatorId}
  AND event.id > COALESCE(#{afterCursor}, 0)
ORDER BY event.id ASC
LIMIT #{limit}
